import React from 'react';
import { Navigate } from 'react-router-dom';
import { usePublicPricingVisibility } from '../hooks/usePublicPricingVisibility';
import PricingPage from './PricingPage';
import RouteLoadingGate from './RouteLoadingGate';

const PricingRouteGate: React.FC = () => {
  const { pricingVisible, loading } = usePublicPricingVisibility();

  if (loading) {
    return <RouteLoadingGate message="Loading pricing…" minHeight="40vh" />;
  }

  if (!pricingVisible) {
    return <Navigate to="/" replace />;
  }

  return <PricingPage />;
};

export default PricingRouteGate;
