import React from 'react';
import { Box, Button, LinearProgress, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { useMsmeSetupProgress } from '../../hooks/useMsmeSetupProgress';
import {
  SIDEBAR_WORKSPACE_BORDER,
  SIDEBAR_WORKSPACE_TEXT_PRIMARY,
  SIDEBAR_WORKSPACE_TEXT_SECONDARY,
} from '../../theme';

const SidebarSetupProgress: React.FC = () => {
  const navigate = useNavigate();
  const { loading, progress, nextStep } = useMsmeSetupProgress();

  if (loading || progress.allComplete || !nextStep) {
    return null;
  }

  const nextStepIndex = progress.steps.findIndex((step) => !step.complete);

  return (
    <Box
      sx={{
        mx: 1.5,
        mb: 1.5,
        p: 1.5,
        borderRadius: 1.5,
        border: '1px solid',
        borderColor: SIDEBAR_WORKSPACE_BORDER,
        bgcolor: 'rgba(76, 175, 80, 0.1)',
      }}
    >
      <Typography
        variant="overline"
        sx={{
          display: 'block',
          fontWeight: 700,
          letterSpacing: 0.8,
          color: SIDEBAR_WORKSPACE_TEXT_SECONDARY,
          mb: 0.5,
        }}
      >
        Setup progress
      </Typography>
      <Typography
        variant="body2"
        sx={{ fontWeight: 600, color: SIDEBAR_WORKSPACE_TEXT_PRIMARY, mb: 0.5, lineHeight: 1.4 }}
      >
        Step {nextStepIndex + 1} of {progress.totalCount}: {nextStep.label}
      </Typography>
      <LinearProgress
        variant="determinate"
        value={progress.percent}
        sx={{ height: 6, borderRadius: 1, mb: 1 }}
      />
      <Typography variant="caption" sx={{ color: SIDEBAR_WORKSPACE_TEXT_SECONDARY, display: 'block', mb: 1 }}>
        {nextStep.description}
        {nextStep.estimatedMinutes ? ` · ~${nextStep.estimatedMinutes} min` : ''}
      </Typography>
      <Button
        size="small"
        variant="contained"
        fullWidth
        onClick={() => navigate(nextStep.path)}
        sx={{ textTransform: 'none', fontWeight: 600 }}
      >
        Continue setup
      </Button>
    </Box>
  );
};

export default SidebarSetupProgress;
