import { useCallback, useState } from 'react';
import ApiService from '../services/api';

export type ApplicationWarning = {
  type?: string;
  message?: string;
  action?: string;
  detail?: string;
  documentId?: string;
};

export type WarningResolutionPlan = {
  warningKey: string;
  warning: string;
  agent: string | null;
  label: string;
  autopilot: boolean;
  canAutoResolve: boolean;
};

export type WarningResolutionResult = {
  resolvedCount: number;
  totalWarnings: number;
  resolutions: Array<{
    resolved: boolean;
    warningKey: string;
    agent?: string;
    label?: string;
    warning?: string;
    message?: string;
  }>;
  plan?: WarningResolutionPlan[];
  message: string;
};

export function useWarningResolution() {
  const [resolving, setResolving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<WarningResolutionResult | null>(null);

  const resolveWarnings = useCallback(async (
    warnings: ApplicationWarning[],
    options?: { period?: string; documentId?: string; applyChanges?: boolean }
  ) => {
    if (!warnings.length) {
      return null;
    }
    setResolving(true);
    setError(null);
    try {
      const response = await ApiService.resolveApplicationWarnings({
        warnings,
        period: options?.period || 'annual',
        documentId: options?.documentId,
        applyChanges: options?.applyChanges !== false,
      });
      const payload = (response as { data?: WarningResolutionResult })?.data || null;
      setResult(payload);
      return payload;
    } catch (e) {
      const message = e instanceof Error ? e.message : 'Failed to resolve warnings';
      setError(message);
      return null;
    } finally {
      setResolving(false);
    }
  }, []);

  const reset = useCallback(() => {
    setResult(null);
    setError(null);
  }, []);

  return {
    resolving,
    error,
    result,
    resolveWarnings,
    reset,
  };
}
