import React from 'react';
import { Alert, Box, Link, Stack, Typography } from '@mui/material';
import {
  Computer as WebIcon,
  PhoneIphone as MobileIcon,
} from '@mui/icons-material';
import {
  MOBILE_APP_URL,
  PLATFORM_TASK_HANDOFFS,
  type PlatformTaskId,
} from '../constants/platformTaskHandoff';

export interface PlatformTaskHandoffProps {
  taskId: PlatformTaskId;
  /** When true, use a compact inline layout. */
  compact?: boolean;
}

const PlatformTaskHandoff: React.FC<PlatformTaskHandoffProps> = ({ taskId, compact = false }) => {
  const config = PLATFORM_TASK_HANDOFFS[taskId];
  const isWebPreferred = config.recommendedSurface === 'web';

  if (compact) {
    return (
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
        {isWebPreferred ? (
          <>
            <WebIcon sx={{ fontSize: 14, verticalAlign: 'text-bottom', mr: 0.5 }} />
            {config.webCta || config.webSummary}
          </>
        ) : (
          <>
            <MobileIcon sx={{ fontSize: 14, verticalAlign: 'text-bottom', mr: 0.5 }} />
            {config.mobileCta || config.mobileSummary}
          </>
        )}
      </Typography>
    );
  }

  return (
    <Alert
      severity="info"
      icon={isWebPreferred ? <WebIcon /> : <MobileIcon />}
      sx={{ mb: 2 }}
    >
      <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
        {config.title}
      </Typography>
      <Stack spacing={0.75}>
        <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-start' }}>
          <WebIcon fontSize="small" color={isWebPreferred ? 'primary' : 'disabled'} sx={{ mt: 0.25 }} />
          <Typography variant="body2" color={isWebPreferred ? 'text.primary' : 'text.secondary'}>
            <strong>Web:</strong> {config.webSummary}
            {isWebPreferred && config.webCta ? ` — ${config.webCta}.` : ''}
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-start' }}>
          <MobileIcon fontSize="small" color={!isWebPreferred ? 'primary' : 'disabled'} sx={{ mt: 0.25 }} />
          <Typography variant="body2" color={!isWebPreferred ? 'text.primary' : 'text.secondary'}>
            <strong>Mobile:</strong> {config.mobileSummary}
            {!isWebPreferred ? (
              <>
                {' '}
                <Link href={MOBILE_APP_URL} target="_blank" rel="noopener noreferrer">
                  Open mobile app
                </Link>
              </>
            ) : null}
          </Typography>
        </Box>
      </Stack>
    </Alert>
  );
};

export default PlatformTaskHandoff;
